<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useResizeObserver } from '@vueuse/core'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import zhCn from 'element-plus/es/locale/lang/zh-cn'
import * as api from '@/api/modules/attachment'
import { getProjectTimeline } from '@/api/modules/project'
import { useUserStore } from '@/stores/user'
import { useAttachmentViewer } from '@/composables/useAttachmentViewer'
import { ENGINEERING_UPLOAD_ACCEPT, FILE_CATEGORY_OPTIONS, MAX_UPLOAD_FILE_SIZE_BYTES, fileCategoryLabel, formatFileSize } from '@/utils/file'
import { formatDate } from '@/utils/format'
import ReferencePicker from './components/ReferencePicker.vue'
import ReferenceObjectSelect from './components/ReferenceObjectSelect.vue'
import DocumentPreview from './components/DocumentPreview.vue'
const user = useUserStore(), route = useRoute(), router = useRouter(), { downloadFile } = useAttachmentViewer()
const canvas = ref<HTMLElement>(), width = ref(1500)
useResizeObserver(canvas, entries => { width.value = entries[0]?.contentRect.width || 1500 })
const compactUpdate = computed(() => width.value < 1200), narrow = computed(() => width.value < 1000)
const canWrite = computed(() => user.hasPermission('documents:write')), canPublish = computed(() => user.hasPermission('documents:publish'))
const emptyPage = (): api.DocumentPage => ({ content: [], page: 1, size: 50, totalElements: 0, totalPages: 0, counts: { all: 0, released: 0, draft: 0, unlinked: 0 } })
const data = ref(emptyPage()), loading = ref(false), error = ref(''), selected = ref<number[]>([]), moreFilters = ref(false)
const filters = reactive({ keyword: '', fileCategory: '', status: 'all' as api.DocumentStatus, page: 1, size: 50, reference: '', projectId: undefined as number | undefined, nodeKey: '', uploader: '', dates: [] as string[] })
const statuses: { value: api.DocumentStatus; label: string }[] = [{ value: 'all', label: '全部' }, { value: 'released', label: '有正式版本' }, { value: 'draft', label: '待发布' }, { value: 'unlinked', label: '待补关联' }]
const objectOptions = ref<api.ReferenceOption[]>([]), projectOptions = ref<api.ReferenceOption[]>([]), nodeOptions = ref<{ nodeKey: string; title: string }[]>([])
let listGeneration = 0, nodeGeneration = 0, detailGeneration = 0, editorGeneration = 0
const message = (e: unknown) => e instanceof Error ? e.message : '请求失败，请重试'
function query(): api.DocumentQuery {
  const r = objectOptions.value.find(r => api.referenceKey(r) === filters.reference)
  return { page: filters.page, size: filters.size, status: filters.status, ...(filters.keyword.trim() ? { keyword: filters.keyword.trim() } : {}), ...(filters.fileCategory ? { fileCategory: filters.fileCategory } : {}), ...(r ? { referenceType: r.type, referenceId: r.id, partType: r.partType } : {}), ...(filters.projectId ? { projectId: filters.projectId } : {}), ...(filters.nodeKey ? { nodeKey: filters.nodeKey } : {}), ...(filters.uploader.trim() ? { uploader: filters.uploader.trim() } : {}), ...(filters.dates?.length === 2 ? { dateFrom: filters.dates[0], dateTo: filters.dates[1] } : {}) }
}
async function load() {
  const ticket = ++listGeneration, token = user.token; loading.value = true; error.value = ''
  try { const result = await api.getDocuments(query()); if (ticket === listGeneration && token === user.token) { data.value = result; selected.value = [] } }
  catch (e) { if (ticket === listGeneration && token === user.token) error.value = message(e) }
  finally { if (ticket === listGeneration && token === user.token) loading.value = false }
}
function search() { filters.page = 1; void load() }
function reset() { Object.assign(filters, { keyword: '', fileCategory: '', status: 'all', page: 1, reference: '', projectId: undefined, nodeKey: '', uploader: '', dates: [] }); nodeOptions.value = []; if (Object.keys(route.query).length) void router.replace({ path: '/files', query: {} }); else void load() }
const filterReferences = computed({ get: () => objectOptions.value.filter(r => api.referenceKey(r) === filters.reference), set: (values: api.ReferenceOption[]) => { objectOptions.value = values; filters.reference = values[0] ? api.referenceKey(values[0]) : '' } })
const projectReferences = computed({ get: () => filters.projectId ? [projectOptions.value.find(p => p.id === filters.projectId) || { type: 'product' as const, id: filters.projectId, partType: 'ALL' as const, name: `项目 #${filters.projectId}`, code: `#${filters.projectId}` }] : [], set: (values: api.ReferenceOption[]) => { projectOptions.value = values; filters.projectId = values[0]?.id } })
watch(() => filters.projectId, async id => {
  const ticket = ++nodeGeneration, token = user.token; filters.nodeKey = ''; nodeOptions.value = []; if (!id) return
  try { const t = await getProjectTimeline(id); if (ticket === nodeGeneration && token === user.token) nodeOptions.value = t.nodes.map(n => ({ nodeKey: n.nodeKey, title: n.nodeName })) } catch (e) { if (ticket === nodeGeneration && token === user.token) error.value = message(e) }
})
function refs(row: api.DocumentRow, group: 'product'|'sku'|'mold') { return row.references.filter(r => group === 'mold' ? !['product','sku'].includes(r.type) : r.type === group) }
function toggle(id: number, checked: boolean) { selected.value = checked ? [...new Set([...selected.value, id])] : selected.value.filter(v => v !== id) }
const allSelected = computed(() => !!data.value.content.length && data.value.content.every(r => selected.value.includes(r.familyId)))
const detailVisible = ref(false), detailLoading = ref(false), detailError = ref(''), detailTab = ref('preview'), context = ref<api.DocumentRow>(), versions = ref<api.AttachmentVO[]>([]), referenceHistory = ref<api.ReferenceHistory[]>([]), activeVersionId = ref<number>(), detailReferences = ref<api.ReferenceOption[]>([])
const activeVersion = computed(() => versions.value.find(v => v.attachmentId === activeVersionId.value))
const snapshot = computed(() => { try { return JSON.parse(activeVersion.value?.publicationReferencesJson || '[]') as api.ReferenceOption[] } catch { return [] } })
async function openDetail(row: api.DocumentRow, tab = 'preview', versionId?: number) {
  const ticket = ++detailGeneration, token = user.token; context.value = row; detailVisible.value = true; detailTab.value = tab; detailLoading.value = true; detailError.value = ''; versions.value = []; referenceHistory.value = []; activeVersionId.value = versionId || row.latestVersion.attachmentId; detailReferences.value = row.references
  try { const [v, r, h] = await Promise.all([api.getAttachmentVersions(row.latestVersion.attachmentId), api.getDocumentReferences(row.latestVersion.attachmentId), api.getReferenceHistory(row.latestVersion.attachmentId)]); if (ticket === detailGeneration && token === user.token) { versions.value = v; detailReferences.value = r; referenceHistory.value = h } } catch (e) { if (ticket === detailGeneration && token === user.token) detailError.value = message(e) } finally { if (ticket === detailGeneration && token === user.token) detailLoading.value = false }
}
function historyReferences(value: string): api.ReferenceOption[] { try { return JSON.parse(value) } catch { return [] } }
const editorVisible = ref(false), editorMode = ref<'upload'|'references'|'batch'|'version'|'release'>('upload'), editorError = ref(''), saving = ref(false), editorFile = ref<File>(), editorRow = ref<api.DocumentRow>(), beforeReferences = ref<api.DocumentReference[]>([]), editorRefs = ref<api.ReferenceOption[]>([]), pdfs = ref<api.AttachmentVO[]>([]), editorTarget = ref<api.AttachmentVO>(), editorProjects = ref<api.ReferenceOption[]>([]), editorLoading = ref(false)
const form = reactive({ fileCategory: 'drawing', versionNo: 'V1', remark: '', projectId: undefined as number | undefined, reason: '', pdfAttachmentId: null as number | null })
const editorTitles = { upload: '上传文件', references: '维护检索关联', batch: '批量补关联', version: '上传新版本', release: '正式发布' }
const isCad = computed(() => editorTarget.value?.previewType === 'cad' || ['dwg','dxf','step','stp','igs','iges','stl','obj','3dm','prt','sldprt','sldasm','x_t','x_b'].includes(editorTarget.value?.fileExt.toLowerCase() || ''))
async function openEditor(mode: typeof editorMode.value, row?: api.DocumentRow, file?: api.AttachmentVO) {
  const ticket = ++editorGeneration, token = user.token; editorMode.value = mode; editorRow.value = row; editorTarget.value = file || row?.latestVersion; editorFile.value = undefined; editorError.value = ''; editorVisible.value = true; editorRefs.value = row ? [...row.references] : []; beforeReferences.value = editorRefs.value.map(api.referenceIdentity); pdfs.value = []; editorProjects.value = []; Object.assign(form, { fileCategory: row?.latestVersion.fileCategory || 'drawing', versionNo: mode === 'version' ? '' : 'V1', remark: '', projectId: mode==='upload'?filters.projectId:undefined, reason: '', pdfAttachmentId: null })
  if (mode === 'upload') { const r = objectOptions.value.find(r => api.referenceKey(r) === filters.reference); if (r) editorRefs.value = [r] }
  if (!row) return; editorLoading.value = true
  try { const found = await api.getDocumentReferences((file || row.latestVersion).attachmentId); if (ticket !== editorGeneration || token !== user.token) return; editorRefs.value = found; beforeReferences.value = found.map(api.referenceIdentity); if (mode === 'release') { const foundPdfs = await api.getDocumentPdfOptions(editorTarget.value!.attachmentId); if (ticket === editorGeneration && token === user.token) pdfs.value = foundPdfs } } catch (e) { if (ticket === editorGeneration && token === user.token) editorError.value = message(e) } finally { if (ticket === editorGeneration) editorLoading.value = false }
}
const editorProjectReferences = computed({ get: () => form.projectId ? [editorProjects.value.find(p => p.id === form.projectId) || projectOptions.value.find(p => p.id === form.projectId) || { type: 'product' as const, id: form.projectId, partType: 'ALL' as const, name: `项目 #${form.projectId}`, code: `#${form.projectId}` }] : [], set: (values: api.ReferenceOption[]) => { editorProjects.value = values; form.projectId = values[0]?.id } })
function chosenFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; editorFile.value = file; editorError.value = ''; if (file && file.size > MAX_UPLOAD_FILE_SIZE_BYTES) { editorError.value = `单个文件不能超过 ${formatFileSize(MAX_UPLOAD_FILE_SIZE_BYTES)}`; editorFile.value = undefined } }
async function submit() {
  const mode = editorMode.value, target = editorTarget.value, ticket = editorGeneration, token = user.token; editorError.value = ''
  if (saving.value || editorLoading.value) return
  if (['upload','references','batch','release'].includes(mode) && !editorRefs.value.length) { editorError.value = '请至少关联一个产品、SKU 或模具'; return }
  if (['upload','version'].includes(mode) && (!editorFile.value || !form.versionNo.trim())) { editorError.value = '请选择文件并填写版本编号'; return }
  if (mode !== 'upload' && !form.reason.trim()) { editorError.value = '请填写修改或发布原因'; return }
  if (mode === 'release' && isCad.value && !form.pdfAttachmentId) { editorError.value = 'CAD 正式发布须选择 PDF 衍生件'; return }
  if (mode === 'release') { try { await ElMessageBox.confirm(`正式发布 ${target!.originalFileName} · ${target!.versionNo}？本次确认的适用范围将保留。`, '核对正式发布', { confirmButtonText: '确认发布', cancelButtonText: '返回核对' }) } catch { return } }
  if (ticket !== editorGeneration || token !== user.token) return; saving.value = true
  try {
    const references = editorRefs.value.map(api.referenceIdentity)
    if (mode === 'upload') await api.uploadDocument(editorFile.value!, { fileCategory: form.fileCategory, versionNo: form.versionNo.trim(), remark: form.remark.trim(), projectId: form.projectId, references })
    else if (mode === 'references') await api.saveDocumentReferences(target!.attachmentId, references, beforeReferences.value, form.reason.trim())
    else if (mode === 'batch') await api.appendDocumentReferences(data.value.content.filter(r => selected.value.includes(r.familyId)).map(r => r.latestVersion.attachmentId), references, form.reason.trim())
    else if (mode === 'version') await api.uploadAttachmentVersion(target!.attachmentId, editorFile.value!, form.versionNo.trim(), form.reason.trim())
    else await api.publishAttachmentVersion(target!.attachmentId, { reason: form.reason.trim(), itemId: target!.collaborationItemId || null, moldSetId: target!.moldSetId || null, pdfAttachmentId: form.pdfAttachmentId, references })
    if (ticket !== editorGeneration || token !== user.token) return
    editorVisible.value = false; ElMessage.success(mode === 'release' ? '正式版本已发布' : mode === 'version' ? '新版本已保存为草稿' : '已保存'); await load()
    if (detailVisible.value && context.value) { const current = data.value.content.find(r => r.familyId === context.value!.familyId) || context.value; await openDetail(current, detailTab.value) }
  } catch (e) { if (ticket === editorGeneration && token === user.token) editorError.value = message(e) } finally { if (ticket === editorGeneration) saving.value = false }
}
async function remove(row: api.DocumentRow) { try { await ElMessageBox.confirm(`删除草稿 ${row.latestVersion.originalFileName} · ${row.latestVersion.versionNo}？`, '删除草稿', { type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消' }) } catch { return } try { await api.deleteAttachment(row.latestVersion.attachmentId); if (data.value.content.length === 1 && filters.page > 1) filters.page--; await load() } catch (e) { error.value = message(e) } }
function command(action: string, row: api.DocumentRow) { if (action === 'remove') void remove(row); else void openEditor(action as typeof editorMode.value, row) }
function applyRoute() { filters.projectId=Number(route.query.projectId)||undefined; const type = route.query.referenceType as api.ReferenceType, id = Number(route.query.referenceId); if (id && type && type in api.REFERENCE_TYPE_LABELS) { const r: api.ReferenceOption = { type, id, partType: (route.query.partType || 'ALL') as api.DocumentReference['partType'], name: String(route.query.referenceName || api.REFERENCE_TYPE_LABELS[type]), code: String(route.query.referenceCode || `#${id}`) }; objectOptions.value = [r]; filters.reference = api.referenceKey(r) } else filters.reference = ''; search() }
watch(() => route.query, () => { if (route.path === '/files') applyRoute() })
watch(detailVisible, (visible: boolean) => { if (!visible) { detailGeneration++; versions.value = [] } })
watch(editorVisible, (visible: boolean) => { if (!visible) { editorGeneration++; saving.value = false; editorLoading.value = false } })
function invalidate() { listGeneration++; nodeGeneration++; detailGeneration++; editorGeneration++ }
watch(() => user.token, () => { invalidate(); data.value = emptyPage(); selected.value = []; objectOptions.value = []; projectOptions.value = []; nodeOptions.value = []; editorRefs.value = []; editorVisible.value = false; detailVisible.value = false; error.value = ''; loading.value = false }, { flush: 'sync' })
onBeforeUnmount(invalidate); onMounted(applyRoute)
</script>
<template>
  <el-config-provider :locale="zhCn" size="small"><main ref="canvas" class="document-ledger compact-ledger" :class="{ 'is-narrow': narrow, 'compact-update': compactUpdate }">
    <header class="ledger-title"><h1>图纸与 3D 文件</h1><span class="total-count">共 {{ data.totalElements }} 份</span><nav class="status-strip" aria-label="文件状态"><button v-for="s in statuses" :key="s.value" :class="{ active: filters.status === s.value }" @click="filters.status = s.value; search()">{{ s.label }} <span>{{ data.counts[s.value] }}</span></button><div class="selection-tools"><span>已选 {{ selected.length }} 份</span><el-button v-if="canWrite && selected.length" size="small" @click="openEditor('batch')">批量补关联</el-button></div></nav><div class="title-actions"><el-button size="small" @click="load" :loading="loading">刷新</el-button><el-button v-if="canWrite" type="primary" size="small" data-test="upload-document" @click="openEditor('upload')">上传文件</el-button></div></header>
    <section class="ledger-filters"><el-input v-model="filters.keyword" aria-label="搜索图纸" clearable placeholder="搜索文件名／模具编码／产品／型号／SKU" @keyup.enter="search"/><ReferenceObjectSelect class="object-filter" v-model="filterReferences" :multiple="false" placeholder="按品牌／型号筛选关联对象" aria-label="关联对象筛选" /><el-select popper-class="document-reference-options" class="category-filter" v-model="filters.fileCategory" clearable placeholder="文件分类"><el-option v-for="c in FILE_CATEGORY_OPTIONS" :key="c.value" :value="c.value" :label="c.label"/></el-select><el-button size="small" @click="moreFilters = !moreFilters">更多筛选 {{ moreFilters ? '⌃' : '⌄' }}</el-button><el-button size="small" type="primary" @click="search">查询</el-button><el-button size="small" @click="reset">重置</el-button></section>
    <section v-if="moreFilters" class="advanced-filters"><ReferenceObjectSelect class="project-filter" v-model="projectReferences" :multiple="false" :types="['product']" project-only placeholder="所属项目" aria-label="所属项目筛选" /><el-select popper-class="document-reference-options" v-model="filters.nodeKey" clearable placeholder="项目节点" :disabled="!filters.projectId"><el-option v-for="n in nodeOptions" :key="n.nodeKey" :value="n.nodeKey" :label="n.title"/></el-select><el-input v-model="filters.uploader" clearable placeholder="上传人"/><el-date-picker v-model="filters.dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="上传开始日期" end-placeholder="上传结束日期"/></section>

    <el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="error" size="small" @click="load">重试查询</el-button>
    <section class="document-list" v-loading="loading" role="table" aria-label="图纸台账"><div class="document-grid table-head" role="row"><div role="columnheader"><el-checkbox :model-value="allSelected" :indeterminate="!!selected.length && !allSelected" aria-label="全选本页" @update:model-value="(checked: boolean | string | number) => selected = checked ? data.content.map(r => r.familyId) : []"/></div><div role="columnheader">文件名称</div><div role="columnheader">产品／型号</div><div role="columnheader">模具</div><div role="columnheader">SKU</div><div role="columnheader">版本状态</div><div role="columnheader" class="update-cell">更新</div><div role="columnheader">操作</div></div>
    <template v-if="!error"><article v-for="row in data.content" :key="row.familyId" class="document-grid document-row" role="row" :data-family="row.familyId"><div role="cell" class="check-cell"><el-checkbox :model-value="selected.includes(row.familyId)" :aria-label="`选择${row.latestVersion.originalFileName}`" @update:model-value="(checked: boolean | string | number) => toggle(row.familyId, !!checked)"/></div><div role="cell" data-label="文件"><button class="file-link" @click="openDetail(row)">{{ row.latestVersion.originalFileName }}</button><small>{{ fileCategoryLabel(row.latestVersion.fileCategory) }} · {{ row.latestVersion.fileExt.toUpperCase() }} · {{ row.versionCount }} 个版本<span v-if="compactUpdate"> · {{ row.updatedBy || row.latestVersion.createdBy }} {{ formatDate(row.updatedAt || row.latestVersion.createdAt) }}</span></small></div><div v-for="group in ['product','mold','sku'] as const" :key="group" role="cell" :data-label="group === 'product' ? '产品／型号' : group === 'mold' ? '模具' : 'SKU'"><template v-if="refs(row,group).length"><div>{{ refs(row,group)[0].name }}</div><small>{{ refs(row,group)[0].code }}<span v-if="refs(row,group)[0].type === 'mold_set'"> · {{ refs(row,group)[0].partType === 'ALL' ? '整套' : refs(row,group)[0].partType }}</span></small><button v-if="refs(row,group).length > 1" class="count-link" @click="openDetail(row, 'references')">共 {{ refs(row,group).length }} 个 · 展开</button></template><span v-else class="unlinked">未关联</span></div><div role="cell" data-label="版本状态"><div>最新 {{ row.latestVersion.versionNo }} <span :class="row.latestVersion.releasedAt ? 'formal-label' : 'draft-label'">{{ row.latestVersion.releasedAt ? '正式' : '草稿' }}</span></div><button v-if="row.formalVersion" class="count-link" @click="openDetail(row,'preview',row.formalVersion.attachmentId)">正式 {{ row.formalVersion.versionNo }}</button><small v-else>尚未正式发布</small></div><div role="cell" class="update-cell" data-label="更新"><div>{{ row.updatedBy || row.latestVersion.createdBy }}</div><small>{{ formatDate(row.updatedAt || row.latestVersion.createdAt) }}</small></div><div role="cell" data-label="操作" class="row-actions"><el-button link size="small" type="primary" @click="openDetail(row)">查看</el-button><el-button link size="small" type="primary" :title="`下载 ${row.latestVersion.versionNo}`" @click="downloadFile(row.latestVersion)">下载</el-button><el-dropdown v-if="canWrite || canPublish" trigger="click" @command="(action: string) => command(action,row)"><el-button link size="small" type="primary" aria-label="文件更多操作">更多 ⌄</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="canWrite" command="references">维护关联</el-dropdown-item><el-dropdown-item v-if="canWrite" command="version">上传新版本</el-dropdown-item><el-dropdown-item v-if="canPublish && !row.latestVersion.releasedAt" command="release">发布 {{ row.latestVersion.versionNo }}</el-dropdown-item><el-dropdown-item v-if="canWrite && !row.latestVersion.releasedAt" command="remove" divided>删除草稿</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></article><div v-if="!data.content.length && !loading" class="empty-state"><strong>当前筛选条件下没有图纸</strong><p>可按模具编码、产品或 SKU 查找，也可上传并关联资料。</p><el-button v-if="canWrite" size="small" type="primary" @click="openEditor('upload')">上传文件</el-button></div></template></section>
    <footer class="ledger-footer"><span>共 {{ data.totalElements }} 份</span><el-pagination size="small" :current-page="filters.page" :page-size="filters.size" :page-sizes="[20,50,100]" :total="data.totalElements" layout="sizes,prev,pager,next" @current-change="(page: number) => { filters.page = page; load() }" @size-change="(size: number) => { filters.size = size; search() }"/></footer>
    <el-drawer v-model="detailVisible" title="图纸详情" size="min(1000px,96vw)"><section v-loading="detailLoading" class="detail-content"><h2>{{ context?.latestVersion.originalFileName }}</h2><el-alert v-if="detailError" :title="detailError" type="error" :closable="false"/><el-button v-if="detailError && context" @click="openDetail(context,detailTab)">重试详情</el-button><el-tabs v-model="detailTab"><el-tab-pane label="预览" name="preview"/><el-tab-pane :label="`关联对象（${detailReferences.length}）`" name="references"/><el-tab-pane :label="`版本历史（${versions.length}）`" name="versions"/></el-tabs><template v-if="detailTab === 'preview' && activeVersion"><div class="version-toolbar"><el-select popper-class="document-reference-options" v-model="activeVersionId" aria-label="预览版本"><el-option v-for="v in versions" :key="v.attachmentId" :value="v.attachmentId" :label="`${v.versionNo} · ${v.releasedAt ? '正式' : '草稿'} · ${v.originalFileName}`"/></el-select><el-button size="small" @click="downloadFile(activeVersion)">下载 {{ activeVersion.versionNo }} 原文件</el-button></div><div class="file-meta"><span>分类：{{ fileCategoryLabel(activeVersion.fileCategory) }}</span><span>大小：{{ formatFileSize(activeVersion.fileSize) }}</span><span>上传：{{ activeVersion.createdBy }} · {{ formatDate(activeVersion.createdAt) }}</span><span>项目：{{ activeVersion.ownerObjectType === 'Document' ? '独立文档' : activeVersion.projectName || detailReferences.find(r => r.type === 'product')?.name || activeVersion.ownerObjectId }}</span><span>节点：{{ activeVersion.timelineStepName || activeVersion.timelineNodeKey || '项目资料' }}</span><span v-if="activeVersion.remark">备注：{{ activeVersion.remark }}</span></div><DocumentPreview :file="activeVersion"/><section v-if="activeVersion.releasedAt" class="publication-scope"><h3>本版本正式发布范围</h3><p>{{ activeVersion.releasedBy }} · {{ formatDate(activeVersion.releasedAt) }} · {{ activeVersion.changeReason }}</p><div v-for="r in snapshot" :key="api.referenceKey(r)">{{ api.REFERENCE_TYPE_LABELS[r.type] }} · {{ r.name || `#${r.id}` }} · {{ r.code }} <span v-if="r.type === 'mold_set'">{{ r.partType === 'ALL' ? '整套' : r.partType }}</span></div><p v-if="!snapshot.length">历史发布未提供完整对象清单。</p></section></template><section v-else-if="detailTab === 'references'" class="relation-detail"><div class="section-tools"><p>检索关联可补正，正式发布范围单独保留。</p><el-button v-if="canWrite && context" size="small" @click="openEditor('references',context)">维护关联</el-button></div><article v-for="r in detailReferences" :key="api.referenceKey(r)" class="relation-card"><span>{{ api.REFERENCE_TYPE_LABELS[r.type] }}</span><strong>{{ r.name }}</strong><div>{{ r.code }}<span v-if="r.type === 'mold_set'"> · {{ r.partType === 'ALL' ? '整套' : r.partType }}</span></div><small>{{ r.subtitle }}</small></article><p v-if="!detailReferences.length">尚未关联对象。</p><h3>关联修改记录</h3><article v-for="h in referenceHistory" :key="h.historyId" class="history-record"><strong>{{ h.actorName }} · {{ formatDate(h.changedAt) }}</strong><p>{{ h.reason }}</p><details><summary>修改前后对象清单</summary><div class="history-before"><span>修改前</span><p v-for="r in historyReferences(h.beforeReferences)" :key="api.referenceKey(r)">{{ api.REFERENCE_TYPE_LABELS[r.type] }} · {{ r.name || `#${r.id}` }} · {{ r.code }}<span v-if="r.type === 'mold_set'"> · {{ r.partType === 'ALL' ? '整套' : r.partType }}</span></p><span>修改后</span><p v-for="r in historyReferences(h.afterReferences)" :key="api.referenceKey(r)">{{ api.REFERENCE_TYPE_LABELS[r.type] }} · {{ r.name || `#${r.id}` }} · {{ r.code }}<span v-if="r.type === 'mold_set'"> · {{ r.partType === 'ALL' ? '整套' : r.partType }}</span></p></div></details></article></section><section v-else-if="detailTab === 'versions'" class="version-history"><article v-for="v in versions" :key="v.attachmentId"><div><strong>{{ v.versionNo }}</strong><span :class="v.releasedAt ? 'formal-label' : 'draft-label'">{{ v.releasedAt ? '正式发布' : '草稿' }}</span><span>{{ v.originalFileName }}</span></div><p>{{ v.changeReason || v.remark || '未填写变更说明' }}</p><small>上传 {{ v.createdBy }} · {{ formatDate(v.createdAt) }}<span v-if="v.releasedAt"> · 发布 {{ v.releasedBy }} · {{ formatDate(v.releasedAt) }}</span></small><div class="version-row-actions"><el-button size="small" @click="activeVersionId = v.attachmentId; detailTab = 'preview'">查看 {{ v.versionNo }}</el-button><el-button size="small" @click="downloadFile(v)">下载 {{ v.versionNo }}</el-button><el-button v-if="canWrite && context" size="small" @click="openEditor('version',context,v)">基于此版更新</el-button><el-button v-if="canPublish && !v.releasedAt && context" size="small" type="primary" @click="openEditor('release',context,v)">正式发布</el-button></div></article></section></section></el-drawer>
    <el-drawer v-model="editorVisible" :title="editorTitles[editorMode]" size="min(760px,96vw)" :show-close="!saving" :close-on-click-modal="!saving" :close-on-press-escape="!saving"><section class="editor-content" v-loading="editorLoading"><p v-if="editorTarget" class="editor-context">{{ editorTarget.originalFileName }} · {{ editorTarget.versionNo }}</p><p v-if="editorMode === 'batch'">为已选 {{ selected.length }} 份图纸追加关联，保留已有对象。</p><el-alert v-if="editorError" :title="editorError" type="error" :closable="false"/><template v-if="editorMode === 'upload' || editorMode === 'version'"><label class="upload-area"><strong>选择图纸或工程文件</strong><input :key="editorGeneration" type="file" :accept="ENGINEERING_UPLOAD_ACCEPT" aria-label="选择上传文件" @change="chosenFile"/><span>{{ editorFile ? `${editorFile.name} · ${formatFileSize(editorFile.size)}` : '支持 PDF、CAD、3D、图片和工程文档' }}</span></label><div class="form-pair"><label v-if="editorMode === 'upload'">文件分类<el-select popper-class="document-reference-options" v-model="form.fileCategory"><el-option v-for="c in FILE_CATEGORY_OPTIONS" :key="c.value" :value="c.value" :label="c.label"/></el-select></label><label>版本编号<el-input v-model="form.versionNo" maxlength="32" placeholder="例如 V2"/></label></div></template><ReferencePicker v-if="['upload','references','batch'].includes(editorMode)" v-model="editorRefs" :disabled="saving||editorLoading"/><template v-if="editorMode === 'release'"><h3>核对本次正式适用范围</h3><div class="release-reference" v-for="r in editorRefs" :key="api.referenceKey(r)">{{ api.REFERENCE_TYPE_LABELS[r.type] }} · {{ r.name }} · {{ r.code }}<span v-if="r.type === 'mold_set'"> · {{ r.partType === 'ALL' ? '整套' : r.partType }}</span></div><label class="editor-label">PDF 衍生件{{ isCad ? '（必填）' : '（选填）' }}<el-select popper-class="document-reference-options" v-model="form.pdfAttachmentId" clearable filterable placeholder="选择同项目或共享明确关联对象的 PDF"><el-option v-for="p in pdfs" :key="p.attachmentId" :value="p.attachmentId" :label="`${p.originalFileName} · ${p.versionNo}`"/></el-select></label></template><label v-if="editorMode !== 'upload'" class="editor-label">{{ editorMode === 'release' ? '发布说明' : '修改原因' }}（必填）<el-input v-model="form.reason" type="textarea" :rows="3" maxlength="2000" placeholder="说明本次变更或确认依据"/></label><details v-if="editorMode === 'upload'" class="upload-more"><summary>更多信息：所属项目、备注</summary><label class="editor-label">所属项目（选填）<ReferenceObjectSelect v-model="editorProjectReferences" :multiple="false" :types="['product']" project-only placeholder="选择所属项目" aria-label="上传文件所属项目" /></label><label class="editor-label">备注<el-input v-model="form.remark" type="textarea" :rows="2" maxlength="500"/></label></details></section><template #footer><div class="editor-footer"><el-button size="small" :disabled="saving" @click="editorVisible = false">取消</el-button><el-button size="small" type="primary" :loading="saving" :disabled="editorLoading" data-test="save-document" @click="submit">{{ editorMode === 'release' ? '确认正式发布' : editorMode === 'version' ? '保存新版本草稿' : '保存' }}</el-button></div></template></el-drawer>
  </main></el-config-provider>
</template>
